<?php $__env->startSection('content'); ?><div class="admin-page-title"><div><span class="eyebrow">PERSONALIZAÇÃO</span><h1>Configurações da loja</h1><p>Altere os dados da Aurora sem editar arquivos de código.</p></div></div><form action="<?php echo e(route('admin.settings.save')); ?>" method="post" enctype="multipart/form-data" class="settings-columns"><?php echo csrf_field(); ?> <?php echo method_field('PUT'); ?><section class="admin-card form-panel"><h2>Identidade da loja</h2><div class="form-grid"><?php $__currentLoopData = ['store_name'=>'Nome da loja','store_subtitle'=>'Subtítulo','store_email'=>'E-mail de contato','store_phone'=>'Telefone','store_whatsapp'=>'WhatsApp com DDI','store_address'=>'Endereço comercial','announcement'=>'Barra de anúncios']; $__env->addLoop($__currentLoopData); foreach($__currentLoopData as $key=>$label): $__env->incrementLoopIndices(); $loop = $__env->getLastLoop(); ?><label><?php echo e($label); ?><input name="<?php echo e($key); ?>" value="<?php echo e(old($key,$settingValues[$key]??'')); ?>" <?php echo e($key==='store_name'?'required':''); ?>></label><?php endforeach; $__env->popLoop(); $loop = $__env->getLastLoop(); ?><label>Cor principal <input type="color" name="primary_color" value="<?php echo e($settingValues['primary_color']??'#171717'); ?>"></label><label>Cor secundária <input type="color" name="accent_color" value="<?php echo e($settingValues['accent_color']??'#b49b84'); ?>"></label><label>Logo <input type="file" accept="image/png,image/jpeg,image/webp" name="logo"></label><label>Favicon <input type="file" accept="image/png,image/x-icon" name="favicon"></label></div><h2>Comunicação e conteúdo</h2><?php $__currentLoopData = ['about_text'=>'Texto sobre a loja','shipping_text'=>'Texto de entrega','returns_text'=>'Política de trocas','seo_title'=>'Título SEO','seo_description'=>'Descrição SEO']; $__env->addLoop($__currentLoopData); foreach($__currentLoopData as $key=>$label): $__env->incrementLoopIndices(); $loop = $__env->getLastLoop(); ?><label><?php echo e($label); ?><textarea rows="3" name="<?php echo e($key); ?>"><?php echo e(old($key,$settingValues[$key]??'')); ?></textarea></label><?php endforeach; $__env->popLoop(); $loop = $__env->getLastLoop(); ?></section><aside><section class="admin-card form-panel"><h2>Conexões e redes sociais</h2><label>Instagram <input type="url" name="social_instagram" value="<?php echo e($settingValues['social_instagram']??''); ?>"></label><label>Facebook <input type="url" name="social_facebook" value="<?php echo e($settingValues['social_facebook']??''); ?>"></label><label>Limite frete grátis (R$) <input type="number" step="0.01" name="free_shipping_min" value="<?php echo e($settingValues['free_shipping_min']??299); ?>"></label><p class="mini-hint">Os fretes estão configurados em modo de teste. Para preço dinâmico, conecte uma transportadora real.</p><div class="payment-demo"><b>Integrações</b><p>Pagamento: <?php echo e(config('shop.payment_mode')==='demo'?'Demonstrativo':'Configuração externa'); ?></p><p>Frete: <?php echo e(config('shop.shipping_mode')==='demo'?'Demonstrativo':'Externo'); ?></p><p>Chaves privadas ficam no .env e nunca são exibidas aqui.</p></div></section><div class="editor-actions"><button class="btn btn-dark block">Salvar configurações →</button></div></aside></form><?php $__env->stopSection(); ?>

